-- One-time TEST-1 pilot setup. This records the centrally stored topic image in BigQuery.
DECLARE v_article_id STRING DEFAULT 'article_6296aabf938f492eafd5a2b010b3f8c9';
DECLARE v_campaign_id STRING DEFAULT 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
DECLARE v_topic_id STRING;

ASSERT (
  SELECT COUNT(*)
  FROM `apex-marketing-n8n.automated_article_creation.articles` a
  JOIN `apex-marketing-n8n.automated_article_creation.interviews` i USING (interview_id)
  JOIN `apex-marketing-n8n.automated_article_creation.doctors` d ON d.doctor_id = a.doctor_id
  WHERE a.article_id = v_article_id
    AND a.campaign_id = v_campaign_id
    AND a.practice_id = 'practice_test_001'
    AND LOWER(d.email) = 'jdold@apexdp.com'
) = 1 AS 'The exact TEST-1 pilot article mapping was not found.';

SET v_topic_id = (
  SELECT i.topic_id
  FROM `apex-marketing-n8n.automated_article_creation.articles` a
  JOIN `apex-marketing-n8n.automated_article_creation.interviews` i USING (interview_id)
  WHERE a.article_id = v_article_id
  LIMIT 1
);

ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_url STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_alt_text STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_source_type STRING;
ALTER TABLE `apex-marketing-n8n.automated_article_creation.campaign_topics`
  ADD COLUMN IF NOT EXISTS featured_image_rights_reference STRING;

UPDATE `apex-marketing-n8n.automated_article_creation.campaign_topics`
SET featured_image_source_url = 'https://apexparent.hostmanpowered.com/wp-content/uploads/2026/09/dental-cleaning-frequency-pilot.png',
    featured_image_alt_text = 'Dentist discussing preventive dental care with a patient in a bright treatment room.',
    featured_image_source_type = 'OPENAI_GENERATED',
    featured_image_rights_reference = 'OpenAI-generated AAC pilot asset; versioned at assets/featured-images/dental-cleaning-frequency-pilot.png; uploaded 2026-09-24.'
WHERE topic_id = v_topic_id AND campaign_id = v_campaign_id;

ASSERT @@row_count = 1 AS 'Exactly one pilot topic must be updated.';

SELECT v_article_id AS article_id, v_topic_id AS topic_id,
  featured_image_source_url, featured_image_alt_text, featured_image_source_type,
  featured_image_rights_reference, 'CONFIGURED' AS status
FROM `apex-marketing-n8n.automated_article_creation.campaign_topics`
WHERE topic_id = v_topic_id AND campaign_id = v_campaign_id;
